//! Golden test of the preload scheduler: runs `tests/golden/preload-scheduler-script.json` (41 cases generated by
//! `oracle-cs preload-scheduler-script` from the C# baseline d92d6aae, inputs in `tests/golden-inputs/`).
//!
//! Red tests (W4-15b): they compile against the stub and fail through `todo!()` until the implementation lands.
//!
//! Comparison rules (contract "Golden package"): per op, `examined` (the order of `get_current_cache_key(entry)` calls)
//! is compared IN ORDER; `preloads` and `log` in order when the case has `workers == 1`, as multisets otherwise;
//! `prefetches` as a multiset; `timers`, `fired`, `consumed`, `resumes`, `preloaded_keys`, `idle`, `tracked` exactly.
//! The synchronous C# fake maps onto the threaded scheduler by waiting for each kick's handle (10 s guard) and, for
//! `fire_timer`, for a NEW resumed run.
//!
//! Environment: the case runs with `PHOTOREVIEW_RS_DIAG_PRELOAD_WORKERS` unset (the scheduler injects an empty
//! environment through `env_lookup`, see `Setup`). The fake probe answers `load < maximumLoad` and reports the snapshot
//! `((load * 100) as u32, 16 GiB)` (C# `(uint)(Load * 100)`).

mod common;

use std::collections::{HashMap, HashSet};
use std::sync::atomic::{AtomicI64, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use common::preload_fakes::*;
use pr_core::abstractions::{MemoryProbe, MemorySnapshot};
use pr_core::catalog::types::CatalogEntry;
use pr_core::sync::CancelToken;
use pr_imaging::cache_key::{ImageCacheKey, KeyOptions};
use pr_imaging::decode_types::DecodeBox;
use pr_imaging::decoder_traits::DecodeError;
use pr_imaging::navigation_pace::{NavigationPace, TICKS_PER_SECOND};
use pr_imaging::preload::target::{KeyError, PreloadTarget};
use pr_imaging::preload_order::PreloadWindow;
use pr_test_support::FakeFileSystem;
use pr_test_support::golden;
use serde_json::Value;

const GOLDEN: &str = "preload-scheduler-script";
const DIR: &str = "C:\\w415b";

/// Mutable state of the synchronous C# fake, shared between the target and the ops.
#[derive(Default)]
struct Script {
    /// Index by upper-invariant path.
    index_by_path: HashMap<String, usize>,
    failures: HashMap<usize, String>,
    key_failures: HashMap<usize, String>,
    raw: HashSet<usize>,
    disk_cached: HashSet<usize>,
    examined: Vec<usize>,
    preloads: Vec<usize>,
    prefetches: Vec<usize>,
    cached: HashSet<ImageCacheKey>,
    bytes: i64,
    viewer: i32,
}

/// The golden fake target: failures and key failures are scripted per index; examined/preloads/prefetches are recorded.
struct GoldenTarget {
    fs: Arc<FakeFileSystem>,
    script: Mutex<Script>,
}

impl GoldenTarget {
    fn index_of(&self, path: &str) -> usize {
        *lock(&self.script)
            .index_by_path
            .get(&path.to_ascii_uppercase())
            .expect("fixture path")
    }

    fn key(&self, path: &str) -> ImageCacheKey {
        ImageCacheKey::create(&*self.fs, path, false, DecodeBox::new(100, 100), KeyOptions::default())
            .expect("fixture key")
    }
}

impl PreloadTarget for GoldenTarget {
    fn try_get_cached_preview_for_path(&self, path: &str) -> bool {
        lock(&self.script).cached.contains(&self.key(path))
    }

    fn try_get_cached_preview(&self, key: &ImageCacheKey) -> bool {
        lock(&self.script).cached.contains(key)
    }

    fn preload(&self, path: &str, _cancel: &CancelToken) -> Result<(), DecodeError> {
        let index = self.index_of(path);
        lock(&self.script).preloads.push(index);
        let failure = lock(&self.script).failures.get(&index).cloned();
        match failure.as_deref() {
            Some("io") => Err(DecodeError::Io(io_error(std::io::ErrorKind::NotFound, "gone"))),
            Some("access") => Err(DecodeError::Io(io_error(
                std::io::ErrorKind::PermissionDenied,
                "denied",
            ))),
            Some("busy") => Err(DecodeError::busy()),
            Some("missing_codec") => Err(DecodeError::missing_codec()),
            Some("invalid_data") => Err(DecodeError::InvalidData {
                message: "corrupt".to_owned(),
            }),
            Some("foreign_cancel") => Err(DecodeError::Canceled),
            Some("not_cached") => Ok(()),
            _ => {
                let key = self.key(path);
                lock(&self.script).cached.insert(key);
                Ok(())
            }
        }
    }

    fn get_current_cache_key_for_path(&self, path: &str) -> Result<ImageCacheKey, KeyError> {
        Ok(self.key(path))
    }

    fn get_current_cache_key(&self, entry: &CatalogEntry) -> Result<ImageCacheKey, KeyError> {
        let index = self.index_of(entry.path());
        lock(&self.script).examined.push(index);
        match lock(&self.script).key_failures.get(&index).map(String::as_str) {
            Some("io") => Err(KeyError::Io(io_error(std::io::ErrorKind::NotFound, "gone"))),
            Some("access") => Err(KeyError::Io(io_error(std::io::ErrorKind::PermissionDenied, "denied"))),
            Some("argument") => Err(KeyError::Other("invalid argument".into())),
            _ => Ok(self.key(entry.path())),
        }
    }

    fn cache_count(&self) -> i32 {
        i32::try_from(lock(&self.script).cached.len()).unwrap_or(i32::MAX)
    }

    fn cache_bytes(&self) -> i64 {
        lock(&self.script).bytes
    }

    fn active_viewer_decodes(&self) -> i32 {
        lock(&self.script).viewer
    }

    fn has_disk_cached_preview(&self, key: &ImageCacheKey) -> bool {
        let script = lock(&self.script);
        script
            .index_by_path
            .get(key.path())
            .is_some_and(|index| script.disk_cached.contains(index))
    }
}

/// C# `LoadProbe`: headroom while `load < maximumLoad`; the snapshot is `((load * 100) as u32, 16 GiB)`.
struct LoadProbe(Mutex<f64>);

impl MemoryProbe for LoadProbe {
    fn has_headroom(&self, maximum_load: f64, _reserve_bytes: i64) -> bool {
        *lock(&self.0) < maximum_load
    }

    fn get_snapshot(&self) -> Option<MemorySnapshot> {
        let load = *lock(&self.0);
        Some(MemorySnapshot {
            load_percent: (load * 100.0) as u32,
            available_bytes: 16 << 30,
        })
    }
}

/// Golden log: plain messages, ordered, drained per op.
fn golden_log() -> Arc<CaptureLog> {
    CaptureLog::plain(true)
}

/// Runs one case; returns the mismatches (empty = the case matches the C# oracle).
fn run_case(case: &Value) -> Vec<String> {
    let name = case["name"].as_str().unwrap_or("?").to_owned();
    let count = case["count"].as_u64().expect("count") as usize;
    let workers = case["workers"].as_i64().expect("workers") as i32;
    let forward = case["forward"].as_i64().expect("forward") as i32;
    let backward = case["backward"].as_i64().expect("backward") as i32;
    let threshold = case["threshold"].as_i64().expect("threshold");

    let fs = fake_fs();
    let mut script = Script::default();
    let mut paths = Vec::new();
    for i in 0..count {
        let raw = case["raw_indices"]
            .as_array()
            .is_some_and(|a| a.iter().any(|v| v.as_u64() == Some(i as u64)));
        let extension = if raw { "cr3" } else { "jpg" };
        let path = format!("{DIR}\\img-{i:02}.{extension}");
        fs.add_file(&path, b"image");
        script.index_by_path.insert(path.to_ascii_uppercase(), i);
        if raw {
            script.raw.insert(i);
        }
        paths.push(path);
    }
    for (key, kind) in case["failures"].as_object().into_iter().flatten() {
        script
            .failures
            .insert(key.parse().expect("index"), kind.as_str().unwrap_or("").to_owned());
    }
    for (key, kind) in case["key_failures"].as_object().into_iter().flatten() {
        script
            .key_failures
            .insert(key.parse().expect("index"), kind.as_str().unwrap_or("").to_owned());
    }
    for index in case["disk_cached"]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(Value::as_u64)
    {
        script.disk_cached.insert(index as usize);
    }
    script.bytes = case["cache_bytes"].as_i64().unwrap_or(0);
    script.viewer = case["viewer"].as_i64().unwrap_or(0) as i32;
    let target = Arc::new(GoldenTarget {
        fs: Arc::clone(&fs),
        script: Mutex::new(script),
    });
    for index in case["cached"]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(Value::as_u64)
    {
        let key = target.key(&paths[index as usize]);
        lock(&target.script).cached.insert(key);
    }

    let load = Arc::new(LoadProbe(Mutex::new(case["load"].as_f64().unwrap_or(0.0))));
    let clock = Arc::new(AtomicI64::new(1_000_000));
    // A clock that advances 10 s per read: key intervals never form a burst (the C# fake pace never bursts).
    let pace_clock = Arc::clone(&clock);
    let pace = Arc::new(NavigationPace::with_timestamp(Box::new(move || {
        pace_clock.fetch_add(10 * TICKS_PER_SECOND, Ordering::SeqCst)
    })));
    let timers = ManualTimers::new();
    let log = golden_log();
    let mut setup = Setup::new(workers, PreloadWindow::new(forward, backward))
        .full_folder_threshold(threshold)
        .probe(load.clone())
        .timers(timers.clone())
        .pace(pace)
        .log(&log);
    if let Some(limit) = case["memory_load_limit"].as_f64() {
        setup = setup.memory_load_limit(limit);
    }
    if case["prefetch"].as_bool().unwrap_or(false) {
        let recorder = Arc::clone(&target);
        setup = setup.prefetch(move |path, _cancel| {
            let index = recorder.index_of(path);
            lock(&recorder.script).prefetches.push(index);
            Ok(())
        });
    }
    // The oracle's entries carry scan metadata `WithMetadata(1000 + i, ..)`: the length feeds the whole-folder estimate
    // (`estimatedBytes` of the policy line; the write time is never read by this fake, which keys by path).
    let entries: Arc<[CatalogEntry]> = paths
        .iter()
        .enumerate()
        .map(|(i, p)| {
            let mut entry = CatalogEntry::new(p.clone()).expect("fixture path");
            entry.length = Some(1000 + i as i64);
            entry
        })
        .collect::<Vec<_>>()
        .into();
    let scheduler = create(&target, &entries, setup);

    let mut mismatches = Vec::new();
    let ops = case["ops"].as_array().cloned().unwrap_or_default();
    let results = case["results"].as_array().cloned().unwrap_or_default();
    for (step, (op, expected)) in ops.iter().zip(results.iter()).enumerate() {
        let before_timers = timers.created();
        let op_name = op["op"].as_str().unwrap_or("");
        let mut actual_fired: Option<bool> = None;
        let mut actual_consumed: Option<bool> = None;
        let resumes_before = scheduler.resumes_for_tests();
        match op_name {
            "preload_around" => {
                let center = op["center"].as_i64().expect("center") as i32;
                assert!(
                    finished(&scheduler.preload_around(center)),
                    "{name}: kick {step} completes"
                );
            }
            "notify_navigation" => scheduler.notify_navigation(op["index"].as_i64().expect("index") as i32),
            "set_failure" => {
                let index = op["index"].as_u64().expect("index") as usize;
                let kind = op["kind"].as_str().unwrap_or("").to_owned();
                lock(&target.script).failures.insert(index, kind);
            }
            "consume_key" => {
                let index = op["index"].as_u64().expect("index") as usize;
                actual_consumed = Some(scheduler.try_consume_preloaded_key(&target.key(&paths[index])));
            }
            "remove_keys_for_path" => {
                let index = op["index"].as_u64().expect("index") as usize;
                scheduler.remove_preloaded_keys_for_path(target.key(&paths[index]).path());
            }
            "evict" => {
                let index = op["index"].as_u64().expect("index") as usize;
                lock(&target.script).cached.remove(&target.key(&paths[index]));
            }
            "clear_preloaded_keys" => scheduler.clear_preloaded_keys(),
            "cancel" => scheduler.cancel(),
            "dispose" => scheduler.dispose(),
            "fire_timer" => match timers.pending_index() {
                Some(index) => {
                    actual_fired = Some(true);
                    timers.fire(index);
                    if scheduler.resumes_for_tests() > resumes_before {
                        let resumed = scheduler.resumed_run_for_tests().expect("a resumed run");
                        assert!(finished(&resumed), "{name}: resumed run completes");
                    }
                }
                None => actual_fired = Some(false),
            },
            "set_load" => *lock(&load.0) = op["value"].as_f64().expect("value"),
            "set_cache_bytes" => lock(&target.script).bytes = op["value"].as_i64().expect("value"),
            "set_viewer" => lock(&target.script).viewer = op["value"].as_i64().expect("value") as i32,
            other => panic!("{name}: unknown op {other}"),
        }

        // Compare the step against the oracle.
        let examined = std::mem::take(&mut lock(&target.script).examined);
        let preloads = std::mem::take(&mut lock(&target.script).preloads);
        let prefetches = std::mem::take(&mut lock(&target.script).prefetches);
        // The oracle's log drops `Preload progress:` lines (contract "Golden package": an enabled log without them).
        let log_lines: Vec<String> = log
            .take_lines()
            .into_iter()
            .filter(|line| !line.starts_with("info: Preload progress:"))
            .collect();
        let timer_dues: Vec<u64> = timers.dues()[before_timers..].iter().map(Duration::as_secs).collect();
        let (lifetimes, runs) = scheduler.tracked_lifetime_counts();
        let mut errs = Vec::new();
        let ctx = StepContext {
            name: &name,
            step,
            op: op_name,
        };
        check(&mut errs, &ctx, expected, "examined", serde_json::json!(examined));
        if workers == 1 {
            check(&mut errs, &ctx, expected, "preloads", serde_json::json!(preloads));
        } else {
            check_multiset(
                &mut errs,
                &ctx,
                expected,
                "preloads",
                preloads.iter().map(|x| *x as u64).collect(),
            );
        }
        if workers == 1 {
            check(&mut errs, &ctx, expected, "log", serde_json::json!(log_lines));
        } else {
            check_multiset_strings(&mut errs, &ctx, expected, "log", log_lines);
        }
        check_multiset(
            &mut errs,
            &ctx,
            expected,
            "prefetches",
            prefetches.iter().map(|x| *x as u64).collect(),
        );
        check(&mut errs, &ctx, expected, "timers", serde_json::json!(timer_dues));
        if let Some(fired) = actual_fired {
            check(&mut errs, &ctx, expected, "fired", serde_json::json!(fired));
        }
        if let Some(consumed) = actual_consumed {
            check(&mut errs, &ctx, expected, "consumed", serde_json::json!(consumed));
        }
        check(
            &mut errs,
            &ctx,
            expected,
            "resumes",
            serde_json::json!(scheduler.resumes_for_tests()),
        );
        check(
            &mut errs,
            &ctx,
            expected,
            "preloaded_keys",
            serde_json::json!(scheduler.preloaded_key_count_for_tests()),
        );
        check(
            &mut errs,
            &ctx,
            expected,
            "idle",
            serde_json::json!(scheduler.is_idle()),
        );
        check(
            &mut errs,
            &ctx,
            expected,
            "tracked",
            serde_json::json!([lifetimes, runs]),
        );
        mismatches.append(&mut errs);
    }
    mismatches
}

/// Where a mismatch happened (case, step, op).
struct StepContext<'a> {
    name: &'a str,
    step: usize,
    op: &'a str,
}

fn check(errs: &mut Vec<String>, ctx: &StepContext<'_>, expected: &Value, key: &str, actual: Value) {
    if let Some(want) = expected.get(key) {
        if want != &actual {
            errs.push(format!(
                "{} step {} ({}) {key}: expected {want}, got {actual}",
                ctx.name, ctx.step, ctx.op
            ));
        }
    }
}

/// `preloads` / `prefetches` as multisets (the threaded scheduler does not keep the oracle's order with several workers).
fn check_multiset(errs: &mut Vec<String>, ctx: &StepContext<'_>, expected: &Value, key: &str, mut actual: Vec<u64>) {
    let mut want: Vec<u64> = expected[key]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(Value::as_u64)
        .collect();
    want.sort_unstable();
    actual.sort_unstable();
    if want != actual {
        errs.push(format!(
            "{} step {} ({}) {key}: expected {want:?}, got {actual:?}",
            ctx.name, ctx.step, ctx.op
        ));
    }
}

fn check_multiset_strings(
    errs: &mut Vec<String>,
    ctx: &StepContext<'_>,
    expected: &Value,
    key: &str,
    mut actual: Vec<String>,
) {
    let mut want: Vec<String> = expected[key]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(|v| v.as_str().map(str::to_owned))
        .collect();
    want.sort();
    actual.sort();
    if want != actual {
        errs.push(format!(
            "{} step {} ({}) {key}: expected {want:?}, got {actual:?}",
            ctx.name, ctx.step, ctx.op
        ));
    }
}

#[test]
fn preload_scheduler_script_matches_the_csharp_oracle() {
    // C#: tests/golden/preload-scheduler-script.json (oracle-cs preload-scheduler-script, d92d6aae)
    let golden = golden::load(GOLDEN);
    assert_eq!(41, golden.cases.len());
    let mut mismatches = Vec::new();
    for case in &golden.cases {
        mismatches.extend(run_case(case));
    }
    assert!(
        mismatches.is_empty(),
        "{} mismatches:\n{}",
        mismatches.len(),
        mismatches.join("\n")
    );
}
